# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YENİDEN DİRİLME (BA\'S) KISSALARINDAN HAYATA İBRETLER (KK.7.2.4)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Bakara 259 (Hz. Üzeyir Kıssası) İbretleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yıkılmış kasabada dirilişin nasıl olacağını sorma</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• 100 yıl uyutulup yeniden diriltilme mucizesi</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Yiyeceğin bozulmaması: Zamanın Allah\'ın elinde oluşu</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Merkebin kemiklerinin göz önünde birleşip dirilmesi</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Sonuç: "Allah\'ın her şeye kadir olduğunu bildim."</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Ölümden Sonra Diriliş (Ba\'s) Haktır</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Bakara 260 (Hz. İbrahim Kıssası) İbretleri</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• "Rabb\'im! Ölüleri nasıl dirilttiğini bana göster" duası</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Amaç şüphe değil: "Kalbim mutmain olsun (yatışsın)"</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Dört kuşun alıştırılıp tepelere konulması</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Çağrılınca kuşların koşarak geri gelmesi</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Sonuç: Allah Azîz\'dir (üstün güç) ve Hakîm\'dir (hikmetli).</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Gözlem ve Tefekkür İmanı Kuvvetlendirir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞADAKİ DİRİLİŞ ÖRNEKLERİ VE AHİRET BİLİNCİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Tabiatta Her Yıl Yaşanan Ba\'s Örnekleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kışın kuruyan toprağın ilkbaharda yeşermesi</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Kuru tohumun toprağa düşüp filizlenmesi</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Gece ve uykudan sonra sabah yeniden uyanış</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• İnsanın hiç yoktan ilk kez yaratılmış olması</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• İlk kez yaratan Allah (cc) yeniden de diriltir</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Her İlkbahar Haşir ve Ba\'sın Delilidir</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Yeniden Dirilme İnancının Hayata Etkisi</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İnsana dünya hayatında yüksek sorumluluk kazandırır.</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Adalet duygusunu ve hak-hukuk bilincini korur.</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Ölüm korkusunu ebedî hayat ümidine dönüştürür.</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Salih amel işlemeye ve iyilik yapmaya teşvik eder.</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Zorluklar karşısında sabır ve tevekkül gücü verir.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Ahiret Bilinci Ahlakı Güzelleştirir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. TEMA GENEL ÖZETİ: SAKİN MİMİN HÂLLERİ VE İDGAM-I MİSLEYN</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Dudak İhfası (مْ + ب)</text>\n  <text x="34" y="100" font-size="11" fill="#334155">• Sakin mimden (مْ) sonra</text>\n  <text x="34" y="120" font-size="11" fill="#334155">  ب (be) harfi gelirse oluşur.</text>\n  <text x="34" y="144" font-size="11" fill="#334155">• Dudaklar bastırılmadan</text>\n  <text x="34" y="164" font-size="11" fill="#334155">  1,5 elif gunneli tutulur.</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Örnek: تَرْمِيهِمْ بِحِجَارَةٍ</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn Meal-Gunne</text>\n  <text x="259" y="100" font-size="11" fill="#334155">• مْ + م veya نْ + ن yan yana</text>\n  <text x="259" y="120" font-size="11" fill="#334155">  geldiğinde gunneli idgam olur.</text>\n  <text x="259" y="144" font-size="11" fill="#334155">• Diğer harflerde (بْ+ب، كْ+ك)</text>\n  <text x="259" y="164" font-size="11" fill="#334155">  idgam-ı misleyn bilâ-gunne olur.</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: لَهُمْ مَا / مَنْ نَشَاءُ</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. Dudak İzharı (مْ + 26 Harf)</text>\n  <text x="484" y="100" font-size="11" fill="#334155">• Sakin mimden sonra ب ve م</text>\n  <text x="484" y="120" font-size="11" fill="#334155">  dışındaki 26 harf gelirse olur.</text>\n  <text x="484" y="144" font-size="11" fill="#334155">• Gunne ve tutma yapılmadan</text>\n  <text x="484" y="164" font-size="11" fill="#334155">  açık ve net şekilde okunur.</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Örnek: أَنْعَمْتَ عَلَيْهِمْ غَيْرِ</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
